//! Renders the Java `Ffi` class — `static native` declarations only.

use crate::gen::parse::FfiFn;
use crate::gen::typemap::{is_generatable, map_type};

pub fn emit_java(fns: &[FfiFn]) -> String {
    let mut out = String::new();
    out.push_str(
        "// @generated by `cargo run -p int2dds-java --bin gen-jni`\n\
         // Source of truth: ffi/src/**.rs\n\
         // DO NOT EDIT — regenerate instead. CI fails on drift.\n\
         package com.intellectus.int2dds.internal.ffi;\n\n\
         /**\n\
         \x20* Raw JNI declarations for the int2DDS C ABI.\n\
         \x20*\n\
         \x20* <p>Entity handles are {@code long} addresses. C strings are UTF-8\n\
         \x20* {@code byte[]}, never {@code String}: JNI uses modified UTF-8, which\n\
         \x20* corrupts NUL bytes and supplementary-plane characters.\n\
         \x20*\n\
         \x20* <p>A {@code byte[]} out parameter is filled in by the native side; a\n\
         \x20* {@code null} {@code byte[]} reaches the C ABI as a null pointer, which\n\
         \x20* means absent rather than empty.\n\
         \x20*/\n\
         public final class Ffi {\n\
         \x20   private Ffi() {}\n\n\
         \x20   /** Native address of a direct ByteBuffer, or 0 if not direct. */\n\
         \x20   static native long directBufferAddress(java.nio.ByteBuffer buf);\n\n",
    );
    for f in fns.iter().filter(|f| is_generatable(f)) {
        let ret = if f.ret == "()" {
            "void".to_string()
        } else {
            map_type(&f.ret).unwrap().java.to_string()
        };
        let params: Vec<String> = f
            .params
            .iter()
            .map(|p| format!("{} {}", map_type(&p.ty).unwrap().java, p.name))
            .collect();
        out.push_str(&format!("    static native {ret} {}({});\n", f.name, params.join(", ")));
    }
    out.push_str("}\n");
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::gen::parse::{FfiFn, Param};

    fn p(name: &str, ty: &str) -> Param {
        Param { name: name.into(), ty: ty.into() }
    }

    fn f(name: &str, params: Vec<Param>, ret: &str) -> FfiFn {
        FfiFn { name: name.into(), params, ret: ret.into(), module: "publisher".into() }
    }

    fn write_serialized() -> FfiFn {
        f(
            "int2dds_datawriter_write_serialized",
            vec![
                p("writer", "*const Int2DdsDataWriter"),
                p("data", "*const u8"),
                p("data_len", "usize"),
                p("key", "*const u8"),
                p("key_len", "usize"),
            ],
            "Int2DdsRet",
        )
    }

    fn native_decls(out: &str) -> Vec<String> {
        out.lines().filter(|l| l.contains("static native")).map(|l| l.trim().to_string()).collect()
    }

    #[test]
    fn declares_the_correct_package_and_class() {
        let out = emit_java(&[write_serialized()]);
        assert!(out.contains("package com.intellectus.int2dds.internal.ffi;"), "{out}");
        assert!(out.contains("public final class Ffi"), "{out}");
    }

    #[test]
    fn emits_a_static_native_method_with_mapped_types() {
        let out = emit_java(&[write_serialized()]);
        assert!(
            out.contains(
                "static native int int2dds_datawriter_write_serialized(\
                 long writer, long data, long data_len, long key, long key_len);"
            ),
            "{out}"
        );
    }

    #[test]
    fn never_emits_java_lang_string() {
        // Checked against the declarations rather than the whole file: the class
        // javadoc says the word String while explaining why none is emitted.
        let out = emit_java(&[f(
            "int2dds_create_topic",
            vec![p("participant", "*const Int2DdsParticipant"), p("topic_name", "*const c_char")],
            "Int2DdsRet",
        )]);
        let decls = native_decls(&out);
        assert!(
            decls.iter().all(|l| !l.contains("String")),
            "no String may cross the boundary: {decls:?}"
        );
        assert!(out.contains("byte[] topic_name"), "{out}");
    }

    #[test]
    fn declares_the_hand_written_direct_buffer_address_method() {
        let out = emit_java(&[write_serialized()]);
        assert!(
            out.contains("static native long directBufferAddress(java.nio.ByteBuffer buf);"),
            "{out}"
        );
    }

    #[test]
    fn output_starts_with_a_do_not_edit_banner() {
        let out = emit_java(&[write_serialized()]);
        assert!(out.starts_with("// @generated"), "{out}");
        assert!(out.contains("DO NOT EDIT"));
    }

    #[test]
    fn unit_returning_functions_become_void() {
        let out = emit_java(&[f(
            "int2dds_condition_seq_delete",
            vec![p("seq", "*mut Int2DdsConditionSeq")],
            "()",
        )]);
        assert!(
            out.contains("static native void int2dds_condition_seq_delete(long seq);"),
            "{out}"
        );
    }

    #[test]
    fn out_parameters_are_declared_as_byte_arrays() {
        // The Rust side writes the FFI result back into this array.
        let out = emit_java(&[f(
            "int2dds_datawriter_get_instance_handle",
            vec![p("writer", "*const Int2DdsDataWriter"), p("handle_out", "*mut [u8; 16]")],
            "Int2DdsRet",
        )]);
        assert!(out.contains("byte[] handle_out"), "{out}");
    }

    #[test]
    fn string_arrays_are_declared_as_byte_array_of_arrays() {
        let out = emit_java(&[f(
            "int2dds_publisher_qos_set_partition",
            vec![
                p("qos", "*mut Int2DdsPublisherQos"),
                p("names", "*const *const c_char"),
                p("count", "usize"),
            ],
            "Int2DdsRet",
        )]);
        assert!(out.contains("byte[][] names"), "{out}");
    }

    #[test]
    fn the_real_surface_declares_every_generatable_function() {
        let fns = crate::gen::parse::parse_ffi_dir(std::path::Path::new("../../ffi/src")).unwrap();
        let out = emit_java(&fns);
        // 453 generated + the hand-written directBufferAddress.
        assert_eq!(native_decls(&out).len(), 454);
        // Both emitters must agree on which functions exist, or the JVM fails
        // to bind a native method at load time rather than at build time.
        let rust = crate::gen::emit_rust::emit_rust(&fns);
        assert_eq!(rust.matches("#[no_mangle]").count() + 1, native_decls(&out).len());
    }
}
